set -e
cd "$(dirname "$0")"
mkdir -p store/reports readonly/reports
cat > q3.csv <<'EOF'
region,total
north,1200
EOF
cat > store/reports/2026-q2.csv <<'EOF'
region,total
north,1100
EOF
cat > readonly/reports/2026-q2.csv <<'EOF'
region,total
north,1100
EOF
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1,DNS:*.s3.us-east-1.amazonaws.com"
surl --directory store --cert server.pem --key server.key --user AKIAIOSFODNN7EXAMPLE:s3cret --allow-uploads --list-directories s3://127.0.0.1:8080/ &
sleep 1
curl -sS --cacert server.pem --connect-to ::127.0.0.1:8080 -u AKIAIOSFODNN7EXAMPLE:s3cret -T q3.csv s3://reports/2026-q3.csv s3://reports/
kill $(jobs -p)
